DROP TABLE IF EXISTS People;

CREATE TABLE People (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(150) NOT NULL,
    endereco VARCHAR(255),
    email VARCHAR(100),
    site_pessoal VARCHAR(100),
    empresa VARCHAR(150),
    biografia TEXT
);

